use super::{ContractRef, EventIdentity};
use bytes::Bytes; use chrono::{DateTime, Utc}; use std::collections::BTreeMap;
#[derive(Debug, Clone, Copy, PartialEq, Eq)] pub enum ExecutionMode { Async, RequestReply, Batch, Scheduled, Replay }
#[derive(Debug, Clone)] pub struct EventEnvelope { pub identity: EventIdentity, pub event_type: String, pub occurred_at: DateTime<Utc>, pub input_contract: ContractRef, pub correlation_id: Option<String>, pub causation_id: Option<String>, pub mode: ExecutionMode, pub payload: Bytes, pub headers: BTreeMap<String, String> }
impl EventEnvelope { pub fn validate(&self, max_payload_bytes: usize) -> Result<(), String> { if self.identity.tenant_id.trim().is_empty() { return Err("tenant_id is required".into()); } if self.identity.event_id.trim().is_empty() { return Err("event_id is required".into()); } if self.identity.partition_key.trim().is_empty() { return Err("partition_key is required".into()); } if self.event_type.trim().is_empty() { return Err("event_type is required".into()); } if self.input_contract.name.trim().is_empty() || self.input_contract.version.trim().is_empty() || self.input_contract.content_hash.trim().is_empty() { return Err("input contract must be immutable and versioned".into()); } if self.payload.len() > max_payload_bytes { return Err("event payload exceeds configured limit".into()); } serde_json::from_slice::<serde_json::Value>(&self.payload).map_err(|_| "event payload must be valid JSON".to_string())?; Ok(()) } }